`timescale 1ns/1ps

// Self-checking testbench for npu_fp32_add.
// Vectors (src/test/vectors/hx_fp32_add.txt, generated by
// generate_hx_numeric_vectors.py from the hx_numeric golden model): directed
// corner cross products for both add and sub (signed zeros, subnormals,
// min/max normal, Inf, Inf - Inf, NaN payloads, overflow, cancellation),
// halfway rounding cases around 1.0, plus 20000 random cases (raw bit
// patterns, and values with nearby exponents incl. near-total cancellation).
// The driver issues back-to-back operations with random idle gaps; every
// cycle out_valid must equal in_valid delayed by exactly LAT clocks and each
// result must match in issue order. A reset with operations in flight must
// drop them.
// A second instance with SUBNORMALS = 0 (the configuration npu_pe_mp uses)
// runs in lockstep on every vector without subnormal operands whose result
// has an exponent field >= 2 or is zero/Inf/NaN, and must give the same bits.
module tb_npu_fp32_add;
    localparam integer LAT = 3;
    localparam integer MAXV = 32768;

    logic clk = 1'b0;
    logic rst_n;
    logic in_valid = 1'b0;
    logic [31:0] a = '0, b = '0;
    logic sub = 1'b0;
    logic out_valid;
    logic [31:0] y;

    npu_fp32_add dut (
        .clk(clk), .rst_n(rst_n), .in_valid(in_valid), .a(a), .b(b), .sub(sub),
        .out_valid(out_valid), .y(y)
    );

    logic in_valid_ns = 1'b0;
    logic out_valid_ns;
    logic [31:0] y_ns;
    npu_fp32_add #(.SUBNORMALS(0)) dut_ns (
        .clk(clk), .rst_n(rst_n), .in_valid(in_valid_ns), .a(a), .b(b), .sub(sub),
        .out_valid(out_valid_ns), .y(y_ns)
    );
    always #5 clk = ~clk;

    logic [31:0] va [0:MAXV-1];
    logic [31:0] vb [0:MAXV-1];
    logic [31:0] vy [0:MAXV-1];
    logic vs [0:MAXV-1];
    logic vns [0:MAXV-1];   // eligible for the SUBNORMALS = 0 instance
    integer count, file, status, issued, checked, seed, i, gaps, checked_ns;
    logic [LAT-1:0] valid_history;
    reg [8*256-1:0] header;

    task automatic mismatch(input [8*80-1:0] what);
        begin
            $display("MISMATCH tb_npu_fp32_add: %0s (vector %0d a=%h b=%h sub=%0d y=%h y_nosub=%h expected %h)",
                     what, checked, va[checked], vb[checked], vs[checked], y, y_ns,
                     vy[checked]);
            $fatal(1);
        end
    endtask

    // One clock: drive the inputs, then check the outputs of the next cycle.
    task automatic cycle(input logic valid, input integer index);
        begin
            @(negedge clk);
            in_valid = valid;
            in_valid_ns = valid && vns[index];
            a = valid ? va[index] : 32'hx;
            b = valid ? vb[index] : 32'hx;
            sub = valid ? vs[index] : 1'bx;
            @(posedge clk);
            #1;
            valid_history = {valid_history[LAT-2:0], valid};
            if (out_valid !== valid_history[LAT-1]) mismatch("out_valid latency");
            if (out_valid) begin
                if (y !== vy[checked]) mismatch("result");
                if (out_valid_ns !== vns[checked]) mismatch("SUBNORMALS=0 out_valid");
                if (vns[checked]) begin
                    if (y_ns !== vy[checked]) mismatch("SUBNORMALS=0 result");
                    checked_ns = checked_ns + 1;
                end
                checked = checked + 1;
            end else if (out_valid_ns !== 1'b0) begin
                mismatch("SUBNORMALS=0 out_valid");
            end
        end
    endtask

    initial begin
        file = $fopen("vectors/hx_fp32_add.txt", "r");
        if (file == 0) file = $fopen("src/test/vectors/hx_fp32_add.txt", "r");
        if (file == 0) begin
            $display("MISMATCH tb_npu_fp32_add: cannot open hx_fp32_add.txt");
            $fatal(1);
        end
        status = $fgets(header, file);
        status = $fscanf(file, "%d\n", count);
        if (count > MAXV || count < 20000) begin
            $display("MISMATCH tb_npu_fp32_add: bad vector count %0d", count);
            $fatal(1);
        end
        for (i = 0; i < count; i = i + 1) begin
            status = $fscanf(file, "%h %h %d %h\n", va[i], vb[i], vs[i], vy[i]);
            if (status != 4) begin
                $display("MISMATCH tb_npu_fp32_add: short vector file at %0d", i);
                $fatal(1);
            end
            vns[i] = !((va[i][30:23] == 8'd0) && (va[i][22:0] != 23'd0)) &&
                     !((vb[i][30:23] == 8'd0) && (vb[i][22:0] != 23'd0)) &&
                     ((vy[i][30:23] >= 8'd2) || (vy[i][30:0] == 31'd0));
        end
        $fclose(file);

        rst_n = 1'b0;  // X -> 0 at time 0 triggers the asynchronous reset
        seed = 32'h136_0003;
        valid_history = '0;
        issued = 0;
        checked = 0;
        checked_ns = 0;
        gaps = 0;
        #1;
        if (out_valid !== 1'b0) mismatch("reset clears out_valid");
        repeat (2) @(negedge clk);
        rst_n = 1'b1;

        // Reset with operations in flight: they must never come out.
        @(negedge clk);
        in_valid = 1'b1;
        a = 32'h3f800000;
        b = 32'h3f800000;
        @(posedge clk);
        #1;
        @(negedge clk);
        in_valid = 1'b0;
        rst_n = 1'b0;
        #1;
        if (out_valid !== 1'b0) mismatch("mid-flight reset clears out_valid");
        @(negedge clk);
        rst_n = 1'b1;
        repeat (LAT + 1) begin
            @(posedge clk);
            #1;
            if (out_valid !== 1'b0) mismatch("flushed operation reappeared");
        end

        while (issued < count) begin
            // Mostly back-to-back, with random bursts of idle cycles.
            if (($random(seed) & 7) == 0) begin
                cycle(1'b0, 0);
                gaps = gaps + 1;
            end else begin
                cycle(1'b1, issued);
                issued = issued + 1;
            end
        end
        repeat (LAT + 2) cycle(1'b0, 0);
        if (checked != count) begin
            $display("MISMATCH tb_npu_fp32_add: %0d of %0d results", checked, count);
            $fatal(1);
        end
        if (checked_ns < count / 2) begin
            $display("MISMATCH tb_npu_fp32_add: only %0d SUBNORMALS=0 checks", checked_ns);
            $fatal(1);
        end
        $display("PASS tb_npu_fp32_add vectors=%0d nosub_vectors=%0d idle_cycles=%0d latency=%0d",
                 count, checked_ns, gaps, LAT);
        $finish;
    end
endmodule
